import { db } from './firebase.js';
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/12.15.0/firebase-firestore.js";

const getState = () => {
  if (typeof window !== 'undefined') {
    if (!window.__DSG_STATE__) {
      window.__DSG_STATE__ = {
        memoryData: null,
        memoryNews: null,
        memoryGallery: null,
        initialized: false
      };
    }
    return window.__DSG_STATE__;
  }
  return { memoryData: null, memoryNews: null, memoryGallery: null, initialized: false };
};

// Lightweight IndexedDB helper for resilient offline storage beyond 5MB
const openDB = () => {
  return new Promise((resolve) => {
    try {
      const req = indexedDB.open('dsg_database_v2', 1);
      req.onupgradeneeded = (e) => {
        const d = e.target.result;
        if (!d.objectStoreNames.contains('keyval')) {
          d.createObjectStore('keyval');
        }
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
    } catch(e) {
      resolve(null);
    }
  });
};

const idbGet = async (key) => {
  try {
    const database = await openDB();
    if (!database) return null;
    return new Promise((resolve) => {
      const tx = database.transaction('keyval', 'readonly');
      const store = tx.objectStore('keyval');
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) {
    return null;
  }
};

const idbSet = async (key, val) => {
  try {
    const database = await openDB();
    if (!database) return false;
    return new Promise((resolve) => {
      const tx = database.transaction('keyval', 'readwrite');
      const store = tx.objectStore('keyval');
      store.put(val, key);
      tx.oncomplete = () => resolve(true);
      tx.onerror = () => resolve(false);
    });
  } catch (e) {
    return false;
  }
};

const parseArticleDate = (a) => {
  if (!a) return 0;
  if (a.createdAt && typeof a.createdAt === 'number') return a.createdAt;
  const d = a.date || '';
  if (d.includes('-')) {
    const p = d.split('-');
    if (p.length === 3) {
      const dt = new Date(parseInt(p[0]), parseInt(p[1]) - 1, parseInt(p[2])).getTime();
      if (!isNaN(dt) && dt > 0) return dt;
    }
  }
  if (d.includes('.')) {
    const p = d.split('.');
    if (p.length === 3) {
      let yr = parseInt(p[2]);
      if (yr < 100) yr += 2000;
      const dt = new Date(yr, parseInt(p[1]) - 1, parseInt(p[0])).getTime();
      if (!isNaN(dt) && dt > 0) return dt;
    }
  }
  if (a.lastUpdated && typeof a.lastUpdated === 'number') return a.lastUpdated;
  return 0;
};

const sortArticles = (articles) => {
  if (!Array.isArray(articles)) return [];
  return [...articles].sort((a, b) => {
    const timeA = parseArticleDate(a);
    const timeB = parseArticleDate(b);
    if (timeB !== timeA) return timeB - timeA;
    return (parseInt(b.id) || 0) - (parseInt(a.id) || 0);
  });
};

function trySetLocal(key, dataStr) {
  try {
    localStorage.setItem(key, dataStr);
  } catch (e) {
    console.warn("localStorage quota exceeded for key:", key);
  }
}

const loadLocal = (prefix, exactVer) => {
  try {
    const raw = localStorage.getItem(`${prefix}_v${exactVer}`);
    if (raw === null || raw === undefined) return null;
    const data = JSON.parse(raw);
    return data;
  } catch (e) {}
  return null;
};

export const Store = {
  init() {
    const state = getState();

    // Clear all obsolete cache versions
    try {
      for (let i = 1; i <= 100; i++) {
        if (i !== 64) localStorage.removeItem(`dsg_data_v${i}`);
        if (i !== 37) localStorage.removeItem(`dsg_articles_v${i}`);
        if (i !== 26) localStorage.removeItem(`dsg_gallery_v${i}`);
        if (i !== 12) localStorage.removeItem(`dsg_admin_players_v${i}`);
        if (i !== 12) localStorage.removeItem(`dsg_admin_teams_v${i}`);
        if (i !== 22) localStorage.removeItem(`dsg_admin_rounds_v${i}`);
        if (i !== 22) localStorage.removeItem(`dsg_admin_leagues_v${i}`);
      }
    } catch(e) {}

    // Eagerly load synchronous local memory into shared singleton
    state.memoryData = loadLocal('dsg_data', 64) || { currentSeason: "2022/2023", seasons: {} };
    state.memoryNews = loadLocal('dsg_articles', 37) || sortArticles([...(INITIAL_DATA.news || [])]);
    state.memoryGallery = loadLocal('dsg_gallery', 26) || INITIAL_DATA.gallery || [];

    // Ensure state.memoryData.seasons is initialized
    if (!state.memoryData.seasons) state.memoryData.seasons = {};

    const initialLeagues = this.getAdminLeaguesSync();
    initialLeagues.forEach(l => {
      let sKey = l.seasonKey;
      if (!sKey) {
        sKey = (l.name && l.year && !l.name.includes(String(l.year))) ? `${l.name} ${l.year}` : l.name;
      }
      if (sKey && !state.memoryData.seasons[sKey]) {
        state.memoryData.seasons[sKey] = {
          teams: [],
          matches: [],
          stats: { topScorers: [], cards: [] }
        };
      }
    });

    state.initialized = true;

    // Trigger Firebase sync in the background
    this.syncFirebase();
  },

  async syncFirebase() {
    const state = getState();
    const dataRef = doc(db, 'system', 'liga_data');
    const newsRef = doc(db, 'system', 'news_data');
    const galleryRef = doc(db, 'system', 'gallery_data');
    const leagueRef = doc(db, 'system', 'leagues_data');
    const roundsRef = doc(db, 'system', 'rounds_data');

    try {
      const [dataSnap, newsSnap, gallerySnap, leagueSnap, roundsSnap] = await Promise.all([
        getDoc(dataRef), getDoc(newsRef), getDoc(galleryRef), getDoc(leagueRef), getDoc(roundsRef)
      ]);

      let needsMigration = false;
      let hasUpdates = false;

      // Sync Liga Data
      if (dataSnap.exists() && dataSnap.data()?.data) {
        const fbData = dataSnap.data().data;
        const fbTime = dataSnap.data().lastUpdated || fbData.lastUpdated || 0;
        const localData = loadLocal('dsg_data', 64);
        const localTime = localData?.lastUpdated || 0;
        if (localTime >= fbTime && localData && localData.seasons && Object.keys(localData.seasons).length > 0) {
          state.memoryData = localData;
          needsMigration = (localTime > fbTime);
        } else if (fbData && fbData.seasons && Object.keys(fbData.seasons).length > 0) {
          state.memoryData = fbData;
          trySetLocal('dsg_data_v64', JSON.stringify(fbData));
          hasUpdates = true;
        } else {
          try {
            const res = await fetch('data/liga.json');
            if (res.ok) {
              const fileLiga = await res.json();
              state.memoryData = fileLiga;
              trySetLocal('dsg_data_v64', JSON.stringify(fileLiga));
              needsMigration = true;
              hasUpdates = true;
            }
          } catch(e) {}
        }
      } else {
        try {
          const res = await fetch('data/liga.json');
          if (res.ok) {
            const fileLiga = await res.json();
            state.memoryData = fileLiga;
            trySetLocal('dsg_data_v64', JSON.stringify(fileLiga));
            needsMigration = true;
            hasUpdates = true;
          }
        } catch(e) {
          let legacyData = loadLocal('dsg_data', 64) || { currentSeason: "2022/2023", seasons: {} };
          state.memoryData = legacyData;
          needsMigration = true;
        }
      }

      // Sync News - authoritative timestamp comparison
      if (newsSnap.exists() && newsSnap.data() && Array.isArray(newsSnap.data().data)) {
        const fbNews = newsSnap.data().data;
        const fbTime = newsSnap.data().lastUpdated || 0;
        const localTime = parseInt(localStorage.getItem('dsg_news_last_updated')) || 0;

        if (fbTime > localTime) {
          state.memoryNews = sortArticles(fbNews);
          trySetLocal('dsg_articles_v37', JSON.stringify(state.memoryNews));
          await idbSet('dsg_articles', state.memoryNews);
          localStorage.setItem('dsg_news_last_updated', String(fbTime));
          hasUpdates = true;
        } else if (localTime > fbTime) {
          await setDoc(newsRef, { data: state.memoryNews, lastUpdated: localTime }).catch(e => console.error("Firebase save error (news):", e));
        }
      } else {
        if (!state.memoryNews || state.memoryNews.length === 0) {
          state.memoryNews = sortArticles([...(INITIAL_DATA.news || [])]);
        }
        await setDoc(newsRef, { data: state.memoryNews, lastUpdated: Date.now() }).catch(e => console.error("Firebase save error (news):", e));
      }

      // Sync Gallery - authoritative timestamp comparison
      if (gallerySnap.exists() && gallerySnap.data() && Array.isArray(gallerySnap.data().data)) {
        const fbGallery = gallerySnap.data().data;
        const fbTime = gallerySnap.data().lastUpdated || 0;
        const localTime = parseInt(localStorage.getItem('dsg_gallery_last_updated')) || 0;

        if (fbTime > localTime) {
          state.memoryGallery = fbGallery;
          trySetLocal('dsg_gallery_v26', JSON.stringify(state.memoryGallery));
          localStorage.setItem('dsg_gallery_last_updated', String(fbTime));
          hasUpdates = true;
        } else if (localTime > fbTime) {
          await setDoc(galleryRef, { data: state.memoryGallery, lastUpdated: localTime }).catch(e => console.error("Firebase save error (gallery):", e));
        }
      } else {
        if (state.memoryGallery && state.memoryGallery.length > 0) {
          await setDoc(galleryRef, { data: state.memoryGallery, lastUpdated: Date.now() }).catch(e => console.error("Firebase save error (gallery):", e));
        }
      }

      // Auto-sync all leagues to seasons
      if (leagueSnap && leagueSnap.exists() && leagueSnap.data()?.data) {
        const leagues = leagueSnap.data().data;
        if (!state.memoryData.seasons) state.memoryData.seasons = {};
        if (Array.isArray(leagues)) {
          leagues.forEach(l => {
            let sKey = l.seasonKey;
            if (!sKey) {
              sKey = (l.name && l.year && !l.name.includes(String(l.year))) ? `${l.name} ${l.year}` : l.name;
            }
            if (sKey && !state.memoryData.seasons[sKey]) {
              state.memoryData.seasons[sKey] = {
                teams: [],
                matches: [],
                stats: { topScorers: [], cards: [] }
              };
              needsMigration = true;
            }
          });
        }
      }

      // Sanitize Gallery items
      if (state.memoryGallery && Array.isArray(state.memoryGallery)) {
        state.memoryGallery.forEach(album => {
          if (!album.image || album.image.includes('assets/hero') || album.image.includes('sample.jpg') || album.image.startsWith('undefined')) {
            album.image = 'stadion.png';
            needsMigration = true;
          }
          if (album.images && Array.isArray(album.images)) {
            album.images = album.images.map((img, idx) => {
              const url = typeof img === 'string' ? img : (img?.url || '');
              const title = typeof img === 'object' ? img.title : `${album.title || 'Foto'} ${idx + 1}`;
              let cleanUrl = url;
              if (!cleanUrl || cleanUrl.includes('assets/hero') || cleanUrl.includes('sample.jpg') || cleanUrl.startsWith('undefined')) {
                cleanUrl = 'stadion.png';
                needsMigration = true;
              }
              return { url: cleanUrl, title: title || `${album.title} ${idx + 1}` };
            });
          } else {
            album.images = [{ url: 'stadion.png', title: album.title || 'Foto 1' }];
            needsMigration = true;
          }
        });
      }

      // Ensure clean state
      if (!state.memoryData.seasons) state.memoryData.seasons = {};
      if (state.memoryData.teams) { delete state.memoryData.teams; needsMigration = true; }
      if (state.memoryData.matches) { delete state.memoryData.matches; needsMigration = true; }
      if (state.memoryData.stats) { delete state.memoryData.stats; needsMigration = true; }

      if (needsMigration) {
        await setDoc(dataRef, { data: state.memoryData, lastUpdated: Date.now() }).catch(e => console.error("Firebase save error (data):", e));
        await setDoc(newsRef, { data: state.memoryNews, lastUpdated: Date.now() }).catch(e => console.error("Firebase save error (news):", e));
        await setDoc(galleryRef, { data: state.memoryGallery, lastUpdated: Date.now() }).catch(e => console.error("Firebase save error (gallery):", e));
      }
        
      trySetLocal('dsg_data_v64', JSON.stringify(state.memoryData));
      trySetLocal('dsg_articles_v37', JSON.stringify(state.memoryNews));
      trySetLocal('dsg_gallery_v26', JSON.stringify(state.memoryGallery));

      if (hasUpdates) {
        window.dispatchEvent(new Event('data-updated'));
      }
    } catch(e) {
      console.error("Firebase sync failed or timed out. Relying on local cache.", e);
    }
  },
  
  getData() {
    const state = getState();
    return state.memoryData || { seasons: {} };
  },
  
  saveData(data) {
    const state = getState();
    const now = Date.now();
    data.lastUpdated = now;
    state.memoryData = data;
    trySetLocal('dsg_data_v64', JSON.stringify(data));
    setDoc(doc(db, 'system', 'liga_data'), { data, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
    window.dispatchEvent(new CustomEvent('data-updated'));
  },

  getNews() {
    const state = getState();
    return state.memoryNews && state.memoryNews.length > 0 ? state.memoryNews : (INITIAL_DATA.news || []);
  },
  
  getArticle(id) {
    if (!id) return null;
    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    return this.getNews().find(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      if (aId === cleanId || String(a.id) === String(id)) return true;
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aTitleSlug === cleanId;
    });
  },

  deleteArticle(id) {
    const state = getState();
    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    state.memoryNews = (state.memoryNews || []).filter(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aId !== cleanId && String(a.id) !== String(id) && aTitleSlug !== cleanId;
    });
    state.memoryNews = sortArticles(state.memoryNews);
    const now = Date.now();
    localStorage.setItem('dsg_news_last_updated', String(now));
    trySetLocal('dsg_articles_v37', JSON.stringify(state.memoryNews));
    idbSet('dsg_articles', state.memoryNews);
    setDoc(doc(db, 'system', 'news_data'), { data: state.memoryNews, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
    window.dispatchEvent(new CustomEvent('data-updated'));
  },
  
  addNews(title, excerpt, content, image, gallery, author, date, readTime) {
    const state = getState();
    let formattedDate = date;
    if (formattedDate && formattedDate.includes('-')) {
      const p = formattedDate.split('-');
      if (p.length === 3) formattedDate = `${p[2]}.${p[1]}.${p[0]}`;
    }
    if (!formattedDate) {
      const now = new Date();
      formattedDate = `${String(now.getDate()).padStart(2, '0')}.${String(now.getMonth() + 1).padStart(2, '0')}.${now.getFullYear()}`;
    }

    const slug = (title || 'artikel').toLowerCase()
      .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    const newId = slug ? `${slug}-${Date.now().toString().slice(-4)}` : Date.now().toString();
    const now = Date.now();
    const newArticle = {
      id: newId,
      title: title || '',
      excerpt: excerpt || '',
      content: content || `<p>${excerpt || ''}</p>`,
      author: author || "DSG Redaktion",
      readTime: readTime || "2 min read",
      image: image || 'dsg.avif',
      gallery: gallery || [],
      date: formattedDate,
      createdAt: now,
      lastUpdated: now
    };
    if (!Array.isArray(state.memoryNews)) state.memoryNews = [];
    state.memoryNews.unshift(newArticle);
    state.memoryNews = sortArticles(state.memoryNews);
    localStorage.setItem('dsg_news_last_updated', String(now));
    trySetLocal('dsg_articles_v37', JSON.stringify(state.memoryNews));
    idbSet('dsg_articles', state.memoryNews);
    setDoc(doc(db, 'system', 'news_data'), { data: state.memoryNews, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
    window.dispatchEvent(new CustomEvent('data-updated'));
    return newArticle;
  },

  updateNews(id, title, excerpt, content, image, gallery, author, date, readTime) {
    const state = getState();
    let formattedDate = date;
    if (formattedDate && formattedDate.includes('-')) {
      const p = formattedDate.split('-');
      if (p.length === 3) formattedDate = `${p[2]}.${p[1]}.${p[0]}`;
    }

    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    const index = (state.memoryNews || []).findIndex(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aId === cleanId || String(a.id) === String(id) || aTitleSlug === cleanId;
    });
    if (index !== -1) {
      const now = Date.now();
      state.memoryNews[index] = {
        ...state.memoryNews[index],
        title,
        excerpt: excerpt || '',
        content: content || `<p>${excerpt}</p>`,
        image: image || state.memoryNews[index].image || 'dsg.avif',
        gallery: gallery || state.memoryNews[index].gallery || [],
        author: author || state.memoryNews[index].author || "DSG Redaktion",
        date: formattedDate || state.memoryNews[index].date,
        readTime: readTime || state.memoryNews[index].readTime || "2 min read",
        lastUpdated: now
      };
      state.memoryNews = sortArticles(state.memoryNews);
      localStorage.setItem('dsg_news_last_updated', String(now));
      trySetLocal('dsg_articles_v37', JSON.stringify(state.memoryNews));
      idbSet('dsg_articles', state.memoryNews);
      setDoc(doc(db, 'system', 'news_data'), { data: state.memoryNews, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
      window.dispatchEvent(new CustomEvent('data-updated'));
    }
  },

  getLiga(season = (this.getData()?.currentSeason || "2022/2023")) {
    const data = this.getData();
    if (!data.seasons) return [];
    if (data.seasons[season] && data.seasons[season].teams) {
      return data.seasons[season].teams;
    }
    return [];
  },

  getMatches(season = (this.getData()?.currentSeason || "2022/2023")) {
    const data = this.getData();
    if (!data.seasons) return [];
    if (data.seasons[season] && data.seasons[season].matches) {
      return data.seasons[season].matches;
    }
    return [];
  },

  getStats(season = (this.getData()?.currentSeason || "2022/2023")) {
    const data = this.getData();
    if (!data.seasons) return { topScorers: [], cards: [] };
    if (data.seasons[season] && data.seasons[season].stats) {
      return data.seasons[season].stats;
    }
    return { topScorers: [], cards: [] };
  },

  _applyMatchStats(season, match) {
    if (!match.status || !match.score) return;
    const isCancelledHomeWin = match.status === 'Abgesagt 3:0';
    const isCancelledAwayWin = match.status === 'Abgesagt 0:3';
    const isPlayed = match.status === 'Gespielt' || match.status === 'Played';

    if (!isPlayed && !isCancelledHomeWin && !isCancelledAwayWin) return;

    let homeGoals = 0, awayGoals = 0;
    if (isCancelledHomeWin) {
      homeGoals = 3; awayGoals = 0;
    } else if (isCancelledAwayWin) {
      homeGoals = 0; awayGoals = 3;
    } else {
      const parts = match.score.split(':');
      if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        homeGoals = parseInt(parts[0]);
        awayGoals = parseInt(parts[1]);
      } else {
        return;
      }
    }

    const teams = this.getLiga(season);
    const homeTeam = teams.find(t => t.name === match.home);
    const awayTeam = teams.find(t => t.name === match.away);

    if (homeTeam && awayTeam) {
      homeTeam.played = (homeTeam.played || 0) + 1;
      awayTeam.played = (awayTeam.played || 0) + 1;

      homeTeam.goalsFor = (homeTeam.goalsFor || 0) + homeGoals;
      homeTeam.goalsAgainst = (homeTeam.goalsAgainst || 0) + awayGoals;
      homeTeam.goalDiff = homeTeam.goalsFor - homeTeam.goalsAgainst;

      awayTeam.goalsFor = (awayTeam.goalsFor || 0) + awayGoals;
      awayTeam.goalsAgainst = (awayTeam.goalsAgainst || 0) + homeGoals;
      awayTeam.goalDiff = awayTeam.goalsFor - awayTeam.goalsAgainst;

      if (homeGoals > awayGoals) {
        homeTeam.won = (homeTeam.won || 0) + 1;
        homeTeam.points = (homeTeam.points || 0) + 3;
        awayTeam.lost = (awayTeam.lost || 0) + 1;
      } else if (awayGoals > homeGoals) {
        awayTeam.won = (awayTeam.won || 0) + 1;
        awayTeam.points = (awayTeam.points || 0) + 3;
        homeTeam.lost = (homeTeam.lost || 0) + 1;
      } else {
        homeTeam.drawn = (homeTeam.drawn || 0) + 1;
        homeTeam.points = (homeTeam.points || 0) + 1;
        awayTeam.drawn = (awayTeam.drawn || 0) + 1;
        awayTeam.points = (awayTeam.points || 0) + 1;
      }
    }

    if (isPlayed && match.events && Array.isArray(match.events)) {
      const stats = this.getStats(season);
      match.events.forEach(ev => {
        if (ev.type === 'goal' && ev.player) {
          let scorer = stats.topScorers.find(s => s.name === ev.player && s.team === ev.team);
          if (scorer) {
            scorer.goals += 1;
          } else {
            stats.topScorers.push({ name: ev.player, team: ev.team, goals: 1 });
          }
        }
        if ((ev.type === 'yellow' || ev.type === 'yellowRed' || ev.type === 'red') && ev.player) {
          let cardEntry = stats.cards.find(c => c.name === ev.player && c.team === ev.team);
          if (!cardEntry) {
            cardEntry = { name: ev.player, player: ev.player, team: ev.team, yellow: 0, red: 0 };
            stats.cards.push(cardEntry);
          }
          if (ev.type === 'yellow') cardEntry.yellow += (parseInt(ev.count) || 1);
          if (ev.type === 'yellowRed') {
            cardEntry.yellow += 2;
            cardEntry.red += 1;
          }
          if (ev.type === 'red') cardEntry.red += (parseInt(ev.count) || 1);
        }
      });
      stats.topScorers.sort((a, b) => b.goals - a.goals);
    }
  },

  _reverseMatchStats(season, match) {
    if (!match.status || !match.score) return;
    const isCancelledHomeWin = match.status === 'Abgesagt 3:0';
    const isCancelledAwayWin = match.status === 'Abgesagt 0:3';
    const isPlayed = match.status === 'Gespielt' || match.status === 'Played';

    if (!isPlayed && !isCancelledHomeWin && !isCancelledAwayWin) return;

    let homeGoals = 0, awayGoals = 0;
    if (isCancelledHomeWin) {
      homeGoals = 3; awayGoals = 0;
    } else if (isCancelledAwayWin) {
      homeGoals = 0; awayGoals = 3;
    } else {
      const parts = match.score.split(':');
      if (parts.length === 2 && !isNaN(parts[0]) && !isNaN(parts[1])) {
        homeGoals = parseInt(parts[0]);
        awayGoals = parseInt(parts[1]);
      } else {
        return;
      }
    }

    const teams = this.getLiga(season);
    const homeTeam = teams.find(t => t.name === match.home);
    const awayTeam = teams.find(t => t.name === match.away);

    if (homeTeam && awayTeam) {
      homeTeam.played = Math.max(0, (homeTeam.played || 0) - 1);
      awayTeam.played = Math.max(0, (awayTeam.played || 0) - 1);

      homeTeam.goalsFor = Math.max(0, (homeTeam.goalsFor || 0) - homeGoals);
      homeTeam.goalsAgainst = Math.max(0, (homeTeam.goalsAgainst || 0) - awayGoals);
      homeTeam.goalDiff = homeTeam.goalsFor - homeTeam.goalsAgainst;

      awayTeam.goalsFor = Math.max(0, (awayTeam.goalsFor || 0) - awayGoals);
      awayTeam.goalsAgainst = Math.max(0, (awayTeam.goalsAgainst || 0) - homeGoals);
      awayTeam.goalDiff = awayTeam.goalsFor - awayTeam.goalsAgainst;

      if (homeGoals > awayGoals) {
        homeTeam.won = Math.max(0, (homeTeam.won || 0) - 1);
        homeTeam.points = Math.max(0, (homeTeam.points || 0) - 3);
        awayTeam.lost = Math.max(0, (awayTeam.lost || 0) - 1);
      } else if (awayGoals > homeGoals) {
        awayTeam.won = Math.max(0, (awayTeam.won || 0) - 1);
        awayTeam.points = Math.max(0, (awayTeam.points || 0) - 3);
        homeTeam.lost = Math.max(0, (homeTeam.lost || 0) - 1);
      } else {
        homeTeam.drawn = Math.max(0, (homeTeam.drawn || 0) - 1);
        homeTeam.points = Math.max(0, (homeTeam.points || 0) - 1);
        awayTeam.drawn = Math.max(0, (awayTeam.drawn || 0) - 1);
        awayTeam.points = Math.max(0, (awayTeam.points || 0) - 1);
      }
    }

    if (isPlayed && match.events && Array.isArray(match.events)) {
      const stats = this.getStats(season);
      match.events.forEach(ev => {
        if (ev.type === 'goal' && ev.player) {
          let scorer = stats.topScorers.find(s => s.name === ev.player && s.team === ev.team);
          if (scorer) {
            scorer.goals = Math.max(0, scorer.goals - 1);
          }
        }
        if ((ev.type === 'yellow' || ev.type === 'yellowRed' || ev.type === 'red') && ev.player) {
          let cardEntry = stats.cards.find(c => c.name === ev.player && c.team === ev.team);
          if (cardEntry) {
            if (ev.type === 'yellow') cardEntry.yellow = Math.max(0, cardEntry.yellow - (parseInt(ev.count) || 1));
            if (ev.type === 'yellowRed') {
              cardEntry.yellow = Math.max(0, cardEntry.yellow - 2);
              cardEntry.red = Math.max(0, cardEntry.red - 1);
            }
            if (ev.type === 'red') cardEntry.red = Math.max(0, cardEntry.red - (parseInt(ev.count) || 1));
          }
        }
      });
      stats.topScorers = stats.topScorers.filter(s => s.goals > 0);
      stats.cards = stats.cards.filter(c => (c.yellow > 0 || c.red > 0));
    }
  },

  getMatch(season, id) {
    if (!season || id === undefined || id === null) return null;
    const matches = this.getMatches(season);
    return matches.find(m => String(m.id) === String(id) || (typeof m.id === 'number' && m.id === parseInt(id))) || null;
  },

  saveMatch(season, matchData) {
    if (!matchData) return;
    const data = this.getData();
    const matches = (data.seasons && data.seasons[season] && data.seasons[season].matches) || [];
    const exists = matchData.id && matches.some(m => String(m.id) === String(matchData.id));
    if (exists) {
      return this.updateMatch(season, matchData.id, matchData);
    } else {
      return this.addMatch(season, matchData);
    }
  },

  addMatch(season, matchData) {
    const data = this.getData();
    if (!data.seasons[season]) {
      data.seasons[season] = { teams: [], matches: [], stats: { topScorers: [], cards: [] } };
    }
    const matches = data.seasons[season].matches;
    const newId = matches.length > 0 ? Math.max(...matches.map(m => m.id)) + 1 : 1;
    const match = { id: newId, ...matchData };
    matches.push(match);

    this._applyMatchStats(season, match);
    this.saveData(data);
    return match;
  },

  updateMatch(season, matchId, matchData) {
    const data = this.getData();
    if (!data.seasons[season]) return;
    const matches = data.seasons[season].matches;
    const index = matches.findIndex(m => String(m.id) === String(matchId) || (typeof m.id === 'number' && m.id === parseInt(matchId)));
    if (index !== -1) {
      this._reverseMatchStats(season, matches[index]);
      matches[index] = { ...matches[index], ...matchData };
      this._applyMatchStats(season, matches[index]);
      this.saveData(data);
    }
  },

  deleteMatch(season, matchId) {
    const data = this.getData();
    if (!data.seasons[season]) return;
    const matches = data.seasons[season].matches;
    const index = matches.findIndex(m => String(m.id) === String(matchId) || (typeof m.id === 'number' && m.id === parseInt(matchId)));
    if (index !== -1) {
      this._reverseMatchStats(season, matches[index]);
      data.seasons[season].matches = matches.filter(m => String(m.id) !== String(matchId) && (!parseInt(matchId) || m.id !== parseInt(matchId)));
      this.saveData(data);
    }
  },

  addTeam(season, teamData) {
    const data = this.getData();
    if (!data.seasons[season]) {
      data.seasons[season] = { teams: [], matches: [], stats: { topScorers: [], cards: [] } };
    }
    const teams = data.seasons[season].teams;
    const newId = teams.length > 0 ? Math.max(...teams.map(t => t.id)) + 1 : 1;
    const team = {
      id: newId,
      name: teamData.name,
      played: 0, won: 0, drawn: 0, lost: 0,
      goalsFor: 0, goalsAgainst: 0, goalDiff: 0,
      points: 0,
      logo: teamData.logo || "stadion.png"
    };
    teams.push(team);
    this.saveData(data);
    return team;
  },

  updateTeam(season, teamId, teamData) {
    const data = this.getData();
    if (!data.seasons[season]) return;
    const teams = data.seasons[season].teams;
    const index = teams.findIndex(t => t.id === parseInt(teamId));
    if (index !== -1) {
      teams[index] = { ...teams[index], ...teamData };
      this.saveData(data);
    }
  },

  deleteTeam(season, teamId) {
    const data = this.getData();
    if (!data.seasons[season]) return;
    data.seasons[season].teams = data.seasons[season].teams.filter(t => t.id !== parseInt(teamId));
    this.saveData(data);
  },

  recalculateSeason(season) {
    const data = this.getData();
    if (!data.seasons[season]) return;
    const s = data.seasons[season];
    
    // Reset teams
    s.teams.forEach(t => {
      t.played = 0; t.won = 0; t.drawn = 0; t.lost = 0;
      t.goalsFor = 0; t.goalsAgainst = 0; t.goalDiff = 0;
      t.points = 0;
    });

    // Reset stats
    s.stats = { topScorers: [], cards: [] };

    // Replay all played/cancelled matches
    s.matches.forEach(m => {
      this._applyMatchStats(season, m);
    });

    // Sort teams
    s.teams.sort((a, b) => {
      if (b.points !== a.points) return b.points - a.points;
      if (b.goalDiff !== a.goalDiff) return b.goalDiff - a.goalDiff;
      return b.goalsFor - a.goalsFor;
    });

    this.saveData(data);
  },

  getVisibleSeasonItems() {
    const leagues = this.getAdminLeaguesSync();
    if (leagues && leagues.length > 0) {
      return leagues.map(l => {
        const key = l.seasonKey || l.name;
        let name = (l.name || key).trim();
        let year = l.year ? String(l.year).trim() : '';
        if (!year && key) {
          const match = key.match(/\d{4}(\/\d{4})?/);
          if (match) year = match[0];
        }
        if (/^\d{4}$/.test(year)) {
          const nextY = parseInt(year) + 1;
          year = `${year}/${nextY}`;
        }
        if (year && !name.includes(year)) {
          name = `${name} ${year}`;
        } else if (!year && /^\d{4}\/\d{4}$/.test(name)) {
          name = `Saison ${name}`;
        }
        return { key, label: name };
      });
    }
    const data = this.getData();
    if (data && data.seasons && Object.keys(data.seasons).length > 0) {
      return Object.keys(data.seasons).map(s => ({
        key: s,
        label: s.startsWith('DSG') || s.startsWith('1.') || s.startsWith('Saison') || s.startsWith('Liga') ? s : `DSG Liga ${s}`
      }));
    }
    return [];
  },

  getAdminLeaguesSync() {
    const local = loadLocal('dsg_admin_leagues', 22);
    if (local && Array.isArray(local)) return local;
    return [];
  },

  async getAdminLeagues() {
    const local = loadLocal('dsg_admin_leagues', 22);
    if (local && Array.isArray(local) && local.length > 0) return local;

    try {
      const leaguesSnap = await getDoc(doc(db, 'system', 'leagues_data'));
      if (leaguesSnap.exists() && leaguesSnap.data()?.data) {
        let fbLeagues = leaguesSnap.data().data;
        if (Array.isArray(fbLeagues) && fbLeagues.length > 0 && !fbLeagues.some(l => l.year === '2026/2027')) {
          trySetLocal('dsg_admin_leagues_v22', JSON.stringify(fbLeagues));
          return fbLeagues;
        }
      }
    } catch(e) {
      console.warn("Could not fetch leagues from Firebase:", e);
    }

    try {
      const res = await fetch('data/leagues.json');
      if (res.ok) {
        const fileLeagues = await res.json();
        if (Array.isArray(fileLeagues)) {
          trySetLocal('dsg_admin_leagues_v22', JSON.stringify(fileLeagues));
          setDoc(doc(db, 'system', 'leagues_data'), { data: fileLeagues, lastUpdated: Date.now() })
            .catch(e => console.error("Firebase save error (leagues initial):", e));
          return fileLeagues;
        }
      }
    } catch(e) {
      console.warn("Could not fetch data/leagues.json:", e);
    }

    return [];
  },

  saveAdminLeagues(leagues) {
    const cleanLeagues = Array.isArray(leagues) ? leagues : [];
    trySetLocal('dsg_admin_leagues_v22', JSON.stringify(cleanLeagues));
    setDoc(doc(db, 'system', 'leagues_data'), { data: cleanLeagues, lastUpdated: Date.now() })
      .catch(e => console.error("Firebase save error (leagues):", e));
    window.dispatchEvent(new CustomEvent('leagues-updated'));
  },

  deleteLeagueSeason(deletedLeague) {
    if (!deletedLeague) return;
    const data = this.getData();
    if (!data.seasons) return;

    const seasonKey = deletedLeague.seasonKey || deletedLeague.name;

    for (let k in data.seasons) {
      if (k === seasonKey || k === deletedLeague.name) {
        delete data.seasons[k];
      }
    }
    this.saveData(data);
  },

  ensureLeagueSeason(league) {
    if (!league) return;
    const data = this.getData();
    if (!data.seasons) data.seasons = {};
    const sKey = league.seasonKey || league.name || (this.getData()?.currentSeason || '2022/2023');
    if (!data.seasons[sKey]) {
      data.seasons[sKey] = {
        name: league.name || sKey,
        year: league.year || 2022,
        teams: [],
        matches: [],
        scorers: [],
        cards: []
      };
      this.saveData(data);
    }
  },

  setLeagueSeasonTeams(seasonKey, teamNames) {
    if (!seasonKey) return;
    const data = this.getData();
    if (!data.seasons) data.seasons = {};
    if (!data.seasons[seasonKey]) {
      data.seasons[seasonKey] = {
        name: seasonKey,
        teams: [],
        matches: [],
        scorers: [],
        cards: []
      };
    }
    const currentTeams = data.seasons[seasonKey].teams || [];
    const teamMap = new Map();
    currentTeams.forEach(t => {
      if (t && t.name) teamMap.set(t.name.trim().toLowerCase(), t);
    });

    data.seasons[seasonKey].teams = (teamNames || []).map((name, idx) => {
      const existing = teamMap.get(name.trim().toLowerCase());
      if (existing) {
        return { ...existing, rank: idx + 1 };
      }
      return {
        rank: idx + 1,
        name: name,
        played: 0,
        won: 0,
        draw: 0,
        lost: 0,
        goalsFor: 0,
        goalsAgainst: 0,
        goalDiff: 0,
        diff: "0:0",
        points: 0
      };
    });
    this.saveData(data);
  },

  getAdminRoundsSync(seasonName = null) {
    const local = loadLocal('dsg_admin_rounds', 23);
    if (local && Array.isArray(local)) {
      if (!seasonName) return local;
      return local.filter(r => r.seasonKey === seasonName || (!r.seasonKey && seasonName === '2022/2023'));
    }
    return [];
  },

  async getAdminRounds(seasonName = null) {
    const local = loadLocal('dsg_admin_rounds', 23);
    if (local && Array.isArray(local) && local.length > 0) {
      if (!seasonName) return local;
      return local.filter(r => r.seasonKey === seasonName || (!r.seasonKey && seasonName === '2022/2023'));
    }

    try {
      const res = await fetch('data/rounds.json');
      if (res.ok) {
        const fileRounds = await res.json();
        if (Array.isArray(fileRounds)) {
          trySetLocal('dsg_admin_rounds_v23', JSON.stringify(fileRounds));
          setDoc(doc(db, 'system', 'rounds_data'), { data: fileRounds, lastUpdated: Date.now() })
            .catch(e => console.error("Firebase save error (rounds initial):", e));
          if (!seasonName) return fileRounds;
          return fileRounds.filter(r => r.seasonKey === seasonName || (!r.seasonKey && seasonName === '2022/2023'));
        }
      }
    } catch(e) {
      console.warn("Could not fetch data/rounds.json:", e);
    }

    try {
      const roundsSnap = await getDoc(doc(db, 'system', 'rounds_data'));
      if (roundsSnap.exists() && roundsSnap.data()?.data) {
        let fbRounds = roundsSnap.data().data;
        if (Array.isArray(fbRounds) && fbRounds.length > 0 && !fbRounds.some(r => r.jahr === '2026/2027')) {
          trySetLocal('dsg_admin_rounds_v23', JSON.stringify(fbRounds));
          if (!seasonName) return fbRounds;
          return fbRounds.filter(r => r.seasonKey === seasonName || (!r.seasonKey && seasonName === '2022/2023'));
        }
      }
    } catch(e) {
      console.warn("Could not fetch rounds from Firebase:", e);
    }

    return [];
  },

  saveAdminRounds(rounds) {
    const cleanRounds = Array.isArray(rounds) ? rounds : [];
    trySetLocal('dsg_admin_rounds_v23', JSON.stringify(cleanRounds));
    setDoc(doc(db, 'system', 'rounds_data'), { data: cleanRounds, lastUpdated: Date.now() })
      .catch(e => console.error("Firebase save error (rounds):", e));
    window.dispatchEvent(new CustomEvent('rounds-updated'));
  },

  async getAdminPlayers() {
    const local = loadLocal('dsg_admin_players', 12);
    if (local && local.length > 0) return local;

    try {
      const playersSnap = await getDoc(doc(db, 'system', 'players_data'));
      if (playersSnap.exists() && playersSnap.data()?.data) {
        let fbPlayers = playersSnap.data().data;
        if (Array.isArray(fbPlayers) && fbPlayers.length > 0) {
          trySetLocal('dsg_admin_players_v12', JSON.stringify(fbPlayers));
          return fbPlayers;
        }
      }
    } catch(e) {
      console.warn("Could not fetch players from Firebase:", e);
    }

    // Prioritize full original scraped players database (4,386+ entries)
    try {
      const res = await fetch('data/players.json');
      if (res.ok) {
        const filePlayers = await res.json();
        if (filePlayers && filePlayers.length > 0) {
          trySetLocal('dsg_admin_players_v12', JSON.stringify(filePlayers));
          setDoc(doc(db, 'system', 'players_data'), { data: filePlayers, lastUpdated: Date.now() })
            .catch(e => console.error("Firebase save error (players initial):", e));
          return filePlayers;
        }
      }
    } catch(e) {
      console.warn("Could not fetch data/players.json:", e);
    }

    return [];
  },

  saveAdminPlayers(players) {
    trySetLocal('dsg_admin_players_v12', JSON.stringify(players));
    setDoc(doc(db, 'system', 'players_data'), { data: players, lastUpdated: Date.now() })
      .catch(e => console.error("Firebase save error (players):", e));
    window.dispatchEvent(new CustomEvent('players-updated'));
  },

  async getAdminTeams() {
    const local = loadLocal('dsg_admin_teams', 12);
    if (local && local.length > 0) return local;

    try {
      const teamsSnap = await getDoc(doc(db, 'system', 'teams_data'));
      if (teamsSnap.exists() && teamsSnap.data()?.data) {
        let fbTeams = teamsSnap.data().data;
        if (Array.isArray(fbTeams) && fbTeams.length > 0) {
          trySetLocal('dsg_admin_teams_v12', JSON.stringify(fbTeams));
          return fbTeams;
        }
      }
    } catch(e) {
      console.warn("Could not fetch teams from Firebase:", e);
    }

    try {
      const res = await fetch('data/teams.json');
      if (res.ok) {
        const fileTeams = await res.json();
        if (fileTeams && fileTeams.length > 0) {
          trySetLocal('dsg_admin_teams_v12', JSON.stringify(fileTeams));
          setDoc(doc(db, 'system', 'teams_data'), { data: fileTeams, lastUpdated: Date.now() })
            .catch(e => console.error("Firebase save error (teams initial):", e));
          return fileTeams;
        }
      }
    } catch(e) {
      console.warn("Could not fetch data/teams.json:", e);
    }

    return [];
  },

  saveAdminTeams(teams) {
    trySetLocal('dsg_admin_teams_v12', JSON.stringify(teams));
    setDoc(doc(db, 'system', 'teams_data'), { data: teams, lastUpdated: Date.now() })
      .catch(e => console.error("Firebase save error (teams):", e));
    window.dispatchEvent(new CustomEvent('teams-updated'));
  },

  getGallery() {
    const state = getState();
    return Array.isArray(state.memoryGallery) ? state.memoryGallery : [];
  },

  getAlbum(id) {
    if (!id) return null;
    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    return this.getGallery().find(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      if (aId === cleanId || String(a.id) === String(id)) return true;
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aTitleSlug === cleanId;
    });
  },

  deleteAlbum(id) {
    const state = getState();
    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    state.memoryGallery = (state.memoryGallery || []).filter(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aId !== cleanId && String(a.id) !== String(id) && aTitleSlug !== cleanId;
    });
    const now = Date.now();
    localStorage.setItem('dsg_gallery_last_updated', String(now));
    trySetLocal('dsg_gallery_v26', JSON.stringify(state.memoryGallery));
    setDoc(doc(db, 'system', 'gallery_data'), { data: state.memoryGallery, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
    window.dispatchEvent(new CustomEvent('data-updated'));
  },

  addAlbum(title, date, excerpt, coverImage, imagesArray) {
    const state = getState();
    let formattedDate = date;
    if (formattedDate && formattedDate.includes('-')) {
      const p = formattedDate.split('-');
      if (p.length === 3) formattedDate = `${p[2]}.${p[1]}.${p[0]}`;
    }
    if (!formattedDate) {
      const now = new Date();
      formattedDate = `${String(now.getDate()).padStart(2, '0')}.${String(now.getMonth() + 1).padStart(2, '0')}.${now.getFullYear()}`;
    }

    const slug = (title || 'album').toLowerCase()
      .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
    const newId = slug ? `${slug}-${Date.now().toString().slice(-4)}` : Date.now().toString();
    
    // Normalize images array
    const cleanImages = (imagesArray || []).map((img, idx) => {
      if (typeof img === 'string') return { url: img, title: `${title || 'Foto'} ${idx + 1}` };
      return { url: img.url || '', title: img.title || `${title || 'Foto'} ${idx + 1}` };
    });

    const now = Date.now();
    const newAlbum = {
      id: newId,
      title: title || 'Neues Album',
      date: formattedDate,
      excerpt: excerpt || '',
      image: coverImage || (cleanImages[0]?.url || 'stadion.png'),
      images: cleanImages.length > 0 ? cleanImages : [{ url: coverImage || 'stadion.png', title: title || 'Foto 1' }],
      createdAt: now,
      lastUpdated: now
    };

    if (!Array.isArray(state.memoryGallery)) state.memoryGallery = [];
    state.memoryGallery.unshift(newAlbum);
    localStorage.setItem('dsg_gallery_last_updated', String(now));
    trySetLocal('dsg_gallery_v26', JSON.stringify(state.memoryGallery));
    setDoc(doc(db, 'system', 'gallery_data'), { data: state.memoryGallery, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
    window.dispatchEvent(new CustomEvent('data-updated'));
    return newAlbum;
  },

  updateAlbum(id, title, date, excerpt, coverImage, imagesArray) {
    const state = getState();
    let formattedDate = date;
    if (formattedDate && formattedDate.includes('-')) {
      const p = formattedDate.split('-');
      if (p.length === 3) formattedDate = `${p[2]}.${p[1]}.${p[0]}`;
    }

    const cleanId = decodeURIComponent(String(id)).trim().toLowerCase();
    const index = (state.memoryGallery || []).findIndex(a => {
      if (!a) return false;
      const aId = decodeURIComponent(String(a.id || '')).trim().toLowerCase();
      const aTitleSlug = (a.title || '').toLowerCase()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
      return aId === cleanId || String(a.id) === String(id) || aTitleSlug === cleanId;
    });

    if (index !== -1) {
      const cleanImages = (imagesArray || []).map((img, idx) => {
        if (typeof img === 'string') return { url: img, title: `${title || 'Foto'} ${idx + 1}` };
        return { url: img.url || '', title: img.title || `${title || 'Foto'} ${idx + 1}` };
      });

      const now = Date.now();
      state.memoryGallery[index] = {
        ...state.memoryGallery[index],
        title: title || state.memoryGallery[index].title,
        date: formattedDate || state.memoryGallery[index].date,
        excerpt: excerpt !== undefined ? excerpt : state.memoryGallery[index].excerpt,
        image: coverImage || state.memoryGallery[index].image || (cleanImages[0]?.url || 'stadion.png'),
        images: cleanImages.length > 0 ? cleanImages : state.memoryGallery[index].images,
        lastUpdated: now
      };
      localStorage.setItem('dsg_gallery_last_updated', String(now));
      trySetLocal('dsg_gallery_v26', JSON.stringify(state.memoryGallery));
      setDoc(doc(db, 'system', 'gallery_data'), { data: state.memoryGallery, lastUpdated: now }).catch(e => console.error("Firebase save error:", e));
      window.dispatchEvent(new CustomEvent('data-updated'));
    }
  }
};

// Auto-initialize store immediately on script import
if (typeof window !== 'undefined') {
  Store.init();
}
